local SiegeTowerMaker = {}
local PRODUCTS = {
    small_tower = { name = "Majhen oblegovalni stolp", woodCost = 12, ironCost = 3, leatherCost = 3, time = 10, cost = 700, defense = 30, durability = 50, description = "Majhen oblegovalni stolp za hitre napade." },
    medium_tower = { name = "Srednji oblegovalni stolp", woodCost = 16, ironCost = 5, leatherCost = 4, time = 14, cost = 1500, defense = 50, durability = 70, prestige = 4, description = "Srednji oblegovalni stolp z dvignjeno ploščadjo." },
    covered_tower = { name = "Pokriti oblegovalni stolp", woodCost = 18, ironCost = 6, leatherCost = 6, ropeCost = 3, time = 18, cost = 2800, defense = 70, durability = 90, prestige = 8, happiness = 1, description = "Pokriti stolp za zaščito pred streli." },
    tall_siege_tower = { name = "Visoki oblegovalni stolp", woodCost = 22, ironCost = 8, steelCost = 2, leatherCost = 7, ropeCost = 4, time = 22, cost = 5000, defense = 95, durability = 115, prestige = 14, happiness = 2, description = "Visoki stolp za najvišje zidove." },
    silver_adorned_tower = { name = "Srebrno okrašen oblegovalni stolp", woodCost = 22, ironCost = 7, steelCost = 3, silverCost = 2, leatherCost = 7, ropeCost = 4, time = 26, cost = 8500, defense = 120, durability = 140, prestige = 24, happiness = 4, description = "Stolp s srebrnim okrasjem za kraljevo vojsko." },
    royal_grand_siege_tower = { name = "Kraljevski veliki oblegovalni stolp", woodCost = 30, ironCost = 12, steelCost = 5, goldCost = 3, silverCost = 2, leatherCost = 10, ropeCost = 6, jewelCost = 1, time = 32, cost = 16000, defense = 180, durability = 200, prestige = 65, happiness = 13, description = "Veliki kraljevski oblegovalni stolp z zlatim in draguljnim okovjem za kronanje." },
}
local BUILDINGS = {
    workshop = { name = "Stolpna delavnica", cost = { gold = 600, wood = 300, stone = 200 }, upkeep = 15, qualityBonus = 5 },
    siege_yard = { name = "Oblegovalno dvorišče", cost = { gold = 1800, wood = 500, stone = 500, iron = 14 }, upkeep = 35, qualityBonus = 18 },
    carpentry = { name = "Mizarski atelje", cost = { gold = 4000, wood = 600, stone = 800, silver = 50, leather = 10 }, upkeep = 80, qualityBonus = 30 },
    royal_tower_atelier = { name = "Kraljevski atelje stolpov", cost = { gold = 18000, wood = 1500, stone = 1800, gold = 250, jewel = 30 }, upkeep = 350, qualityBonus = 55, prestigeBonus = 55 },
}
SiegeTowerMaker.woodStock = 30; SiegeTowerMaker.ironStock = 14; SiegeTowerMaker.steelStock = 10; SiegeTowerMaker.leatherStock = 12; SiegeTowerMaker.ropeStock = 10; SiegeTowerMaker.silverStock = 8; SiegeTowerMaker.goldStock = 6; SiegeTowerMaker.jewelStock = 6
SiegeTowerMaker.productStock = {}; SiegeTowerMaker.buildings = {}; SiegeTowerMaker.maker = nil; SiegeTowerMaker.activeMaking = {}; SiegeTowerMaker.totalProducts = 0; SiegeTowerMaker.dayTimer = 0
function SiegeTowerMaker.init() SiegeTowerMaker.woodStock=30; SiegeTowerMaker.ironStock=14; SiegeTowerMaker.steelStock=10; SiegeTowerMaker.leatherStock=12; SiegeTowerMaker.ropeStock=10; SiegeTowerMaker.silverStock=8; SiegeTowerMaker.goldStock=6; SiegeTowerMaker.jewelStock=6; SiegeTowerMaker.productStock={}; SiegeTowerMaker.buildings={}; SiegeTowerMaker.maker=nil; SiegeTowerMaker.activeMaking={}; SiegeTowerMaker.totalProducts=0; SiegeTowerMaker.dayTimer=0; print("[SiegeTowerMaker] Royal Siege Tower Maker System initialized (6 products, 4 buildings)") end
function SiegeTowerMaker.hireMaker(n,s) s=s or math.random(55,95); local c=750+s*15; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; SiegeTowerMaker.maker={name=n or ("Stolpar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Stolpar najet: %s (spretnost: %d)",SiegeTowerMaker.maker.name,s),"success") end; return true end
function SiegeTowerMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function SiegeTowerMaker.build(id) local ok,e=SiegeTowerMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(SiegeTowerMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function SiegeTowerMaker.getQualityBonus() local b=0; for _,bd in ipairs(SiegeTowerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function SiegeTowerMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and SiegeTowerMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.ironCost and SiegeTowerMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.steelCost and SiegeTowerMaker.steelStock<(d.steelCost or 0) then return false,"Premalo jekla" end; if d.leatherCost and SiegeTowerMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.ropeCost and SiegeTowerMaker.ropeStock<(d.ropeCost or 0) then return false,"Premalo vrvi" end; if d.silverCost and SiegeTowerMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and SiegeTowerMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and SiegeTowerMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if #SiegeTowerMaker.buildings==0 then return false,"Potrebna delavnica" end; if not SiegeTowerMaker.maker then return false,"Potreben stolpar" end; return true end
function SiegeTowerMaker.make(pt,qty) qty=qty or 1; local ok,e=SiegeTowerMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then SiegeTowerMaker.woodStock=SiegeTowerMaker.woodStock-d.woodCost*qty end; if d.ironCost then SiegeTowerMaker.ironStock=SiegeTowerMaker.ironStock-d.ironCost*qty end; if d.steelCost then SiegeTowerMaker.steelStock=SiegeTowerMaker.steelStock-d.steelCost*qty end; if d.leatherCost then SiegeTowerMaker.leatherStock=SiegeTowerMaker.leatherStock-d.leatherCost*qty end; if d.ropeCost then SiegeTowerMaker.ropeStock=SiegeTowerMaker.ropeStock-d.ropeCost*qty end; if d.silverCost then SiegeTowerMaker.silverStock=SiegeTowerMaker.silverStock-d.silverCost*qty end; if d.goldCost then SiegeTowerMaker.goldStock=SiegeTowerMaker.goldStock-d.goldCost*qty end; if d.jewelCost then SiegeTowerMaker.jewelStock=SiegeTowerMaker.jewelStock-d.jewelCost*qty end; local t=d.time; if SiegeTowerMaker.maker then t=math.max(1,t-math.floor(SiegeTowerMaker.maker.skill/12)) end; table.insert(SiegeTowerMaker.activeMaking,{id="tower_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,defense=d.defense or 0,durability=d.durability or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function SiegeTowerMaker.completeMaking(m) local q=1.0+(SiegeTowerMaker.getQualityBonus()/100); if SiegeTowerMaker.maker then q=q+(SiegeTowerMaker.maker.skill/150) end; q=math.min(2.5,q); SiegeTowerMaker.productStock[m.productType]=(SiegeTowerMaker.productStock[m.productType] or 0)+m.quantity; SiegeTowerMaker.totalProducts=SiegeTowerMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if SiegeTowerMaker.maker then SiegeTowerMaker.maker.itemsMade=SiegeTowerMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then SiegeTowerMaker.maker.skill=math.min(100,SiegeTowerMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Stolp izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"siegetower.completed",{productName=m.productName,defense=m.defense,durability=m.durability}) end end
function SiegeTowerMaker.update(dt) if not _G.state then return end; SiegeTowerMaker.dayTimer=SiegeTowerMaker.dayTimer+dt; if SiegeTowerMaker.dayTimer>=30 then SiegeTowerMaker.dayTimer=0; for i=#SiegeTowerMaker.activeMaking,1,-1 do local m=SiegeTowerMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then SiegeTowerMaker.completeMaking(m); table.remove(SiegeTowerMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(SiegeTowerMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if SiegeTowerMaker.maker then tu=tu+28 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function SiegeTowerMaker.getStats() return {woodStock=SiegeTowerMaker.woodStock,ironStock=SiegeTowerMaker.ironStock,steelStock=SiegeTowerMaker.steelStock,leatherStock=SiegeTowerMaker.leatherStock,ropeStock=SiegeTowerMaker.ropeStock,silverStock=SiegeTowerMaker.silverStock,goldStock=SiegeTowerMaker.goldStock,jewelStock=SiegeTowerMaker.jewelStock,productStock=SiegeTowerMaker.productStock,numBuildings=#SiegeTowerMaker.buildings,hasMaker=SiegeTowerMaker.maker~=nil,makerName=SiegeTowerMaker.maker and SiegeTowerMaker.maker.name or "—",makerSkill=SiegeTowerMaker.maker and SiegeTowerMaker.maker.skill or 0,activeMaking=#SiegeTowerMaker.activeMaking,totalProducts=SiegeTowerMaker.totalProducts} end
return SiegeTowerMaker
